const compactCve = (c) => ({
  id: c.id, severity: c.severity, pkg: c.pkg,
  installedVersion: c.installedVersion || '', fixedVersion: c.fixedVersion || '',
  title: (c.title || '').substring(0, 100), cvss: c.cvss ?? null,
});
const dedupe = (arr) => {
  const seen = new Map();
  for (const c of arr) {
    if (!seen.has(c.id)) seen.set(c.id, compactCve(c));
    else {
      const prev = seen.get(c.id);
      if (c.pkg && !prev.pkg.includes(c.pkg)) prev.pkg += ', ' + c.pkg;
    }
  }
  return [...seen.values()];
};
const cveSort = (a, b) => ({CRITICAL:0,HIGH:1,MEDIUM:2}[a.severity] ?? 9) - ({CRITICAL:0,HIGH:1,MEDIUM:2}[b.severity] ?? 9) || (b.cvss ?? 0) - (a.cvss ?? 0);
const trivyCves = dedupe(d.trivy?.cves || []).sort(cveSort).slice(0, 12);
